export class StockNotFound extends Data.TaggedError("StockNotFound")<{
  readonly sku: string
}> {}

export class InsufficientStock extends Data.TaggedError("InsufficientStock")<{
  readonly sku: string
  readonly available: number
}> {}

export class LedgerUnavailable extends Data.TaggedError("LedgerUnavailable")<{
  readonly reason: string
}> {}

export type WarehouseError =
  | StockNotFound
  | InsufficientStock
  | LedgerUnavailable

export interface WarehouseService {
  readonly available: (
    sku: string
  ) => Effect.Effect<number, StockNotFound | LedgerUnavailable>
  readonly reserve: (
    sku: string,
    quantity: number
  ) => Effect.Effect<void, StockNotFound | InsufficientStock | LedgerUnavailable>
  readonly flush: () => Effect.Effect<void, LedgerUnavailable>
}

const reportFailure = (error: WarehouseError): Effect.Effect<void> =>
  Effect.logWarning("Warehouse operation failed", {
    category: error._tag,
    detail: error.message
  })

export const withWarehouseDiagnostics = (
  service: WarehouseService
): WarehouseService => ({
  available: (sku) =>
    service.available(sku).pipe(Effect.tapError(reportFailure)),
  reserve: (sku, quantity) =>
    service.reserve(sku, quantity).pipe(Effect.tapError(reportFailure)),
  flush: () => service.flush().pipe(Effect.tapError(reportFailure))
})

